#!/usr/bin/env node
/**
 * Stop Hook — Stage0 Wave 2 Enforcement
 *
 * Phase 7 enforcement hardening. Blocks /stage0 verdict output if:
 * - Wave 1 receipt present (confirming stage0 dispatch)
 * - Wave 2 receipt MISSING
 * - case.confidence < 0.8
 * - verdict_class NOT in exempt list
 *
 * Exit codes:
 *   0 — pass (no violation or not a stage0 turn)
 *   2 — BLOCK in enforce mode
 *
 * Override via .ck.json: stage0.wave2Enforcement = "enforce"|"warn"|"off"
 *
 * Plan ref: plans/260413-1751-stage0-brain-evolution/phase-07-enforcement-hardening-multi-branch.md
 */

'use strict';

const fs = require('fs');
const path = require('path');
const os = require('os');

function readCkJson() {
  try {
    const ckPath = path.join(process.cwd(), '.claude', '.ck.json');
    return JSON.parse(fs.readFileSync(ckPath, 'utf8'));
  } catch {
    return {};
  }
}

function getEnforceMode(cfg) {
  return cfg?.stage0?.wave2Enforcement || 'enforce';
}

function readStdinPayload() {
  try {
    const raw = fs.readFileSync(0, 'utf-8').trim();
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

function getLastAssistantText(payload) {
  // Path 1: transcript_path (standard Claude Code hook contract)
  if (payload.transcript_path && fs.existsSync(payload.transcript_path)) {
    try {
      const lines = fs.readFileSync(payload.transcript_path, 'utf8').trim().split('\n');
      for (let i = lines.length - 1; i >= 0; i--) {
        const entry = JSON.parse(lines[i]);
        if (entry.type === 'assistant' || entry.role === 'assistant') {
          const content = entry.content || entry.message?.content;
          if (typeof content === 'string') return content;
          if (Array.isArray(content)) {
            return content
              .filter((b) => b.type === 'text' || !b.type)
              .map((b) => b.text || b.content || '')
              .join('\n');
          }
        }
      }
    } catch {}
  }
  // Fallback paths
  if (typeof payload.assistant_message === 'string') return payload.assistant_message;
  if (typeof payload.message === 'string') return payload.message;
  if (typeof payload.text === 'string') return payload.text;
  return '';
}

function findLatestWave1Receipt(tmpDir) {
  try {
    const files = fs.readdirSync(tmpDir)
      .filter((f) => f.startsWith('stage0-wave1-receipt-') && f.endsWith('.json'))
      .map((f) => ({ name: f, mtime: fs.statSync(path.join(tmpDir, f)).mtimeMs }))
      .sort((a, b) => b.mtime - a.mtime);
    return files.length > 0 ? files[0] : null;
  } catch {
    return null;
  }
}

function parseConfidence(text) {
  // Matches: "Confidence: 0.72" or "confidence: 0.72" or "**Confidence:** 0.72"
  const m = text.match(/\*?\*?[Cc]onfidence[:\s*]+([0-9.]+)/);
  if (m) {
    const v = parseFloat(m[1]);
    if (!isNaN(v)) return v;
  }
  return 1.0; // default: assume high confidence if not parseable
}

function parseVerdictClass(text) {
  // Matches: "VERDICT: PROVISIONAL_MOUNTAIN" or "## VERDICT: KILL"
  const m = text.match(/VERDICT[:\s*]+([A-Z_]+)/);
  return m ? m[1].trim() : '';

