#!/usr/bin/env node
/**
 * stage0-post-audit.cjs — Consolidated Stage0 Audit Hook
 *
 * Merges 8 individual stage0 hooks into one file. Reads stdin ONCE.
 * Auto-routes by payload shape:
 *   - Has tool_name → PreToolUse → cashflow audit (audit 8)
 *   - No tool_name  → Stop hook  → audits 1-7
 *
 * Stop exit codes: 0 = pass, 2 = BLOCK (first failure wins)
 * PreToolUse output: JSON { decision: 'approve'|'block'|'allow', reason? }
 */

'use strict';

const fs = require('fs');
const path = require('path');
const os = require('os');
const { spawnSync } = require('child_process');

let isHookEnabled;
try { ({ isHookEnabled } = require('./lib/ck-config-utils.cjs')); }
catch { isHookEnabled = () => true; }

if (!isHookEnabled('stage0-post-audit')) process.exit(0);

// Read stdin ONCE — shared by all audits
let payload = {};
try {
  const raw = fs.readFileSync(0, 'utf-8').trim();
  if (raw) payload = JSON.parse(raw);
} catch { process.exit(0); }

if (typeof payload.tool_name === 'string') runCashflowAudit(payload);
else runStopAudits(payload);

// ── Shared helpers ─────────────────────────────────────────────────────────────

function getLastAssistantText(p) {
  if (p.transcript_path && fs.existsSync(p.transcript_path)) {
    try {
      const lines = fs.readFileSync(p.transcript_path, 'utf8').trim().split('\n');
      for (let i = lines.length - 1; i >= 0; i--) {
        const e = JSON.parse(lines[i]);
        if (e.type === 'assistant' || e.role === 'assistant') {
          const c = e.content || e.message?.content;
          if (typeof c === 'string') return c;
          if (Array.isArray(c)) return c.filter(b => b.type === 'text' || !b.type).map(b => b.text || b.content || '').join('\n');
        }
      }
    } catch {}
  }
  return p.assistant_message || p.message || p.text || '';
}

function looksLikeVerdict(text) {
  if (!text || text.length < 500) return false;
  return [/\/stage0 verdict/i, /mountain test v2/i, /brain information flow audit/i, /verdict class/i, /VERDICT:/i]
    .filter(r => r.test(text)).length >= 2;
}

function getRecentIntentClass() {
  try {
    const tmpDir = os.tmpdir();
    const files = fs.readdirSync(tmpDir)
      .filter(f => f.startsWith('stage0-intent-class-') && f.endsWith('.json'))
      .map(f => ({ name: f, mtime: fs.statSync(path.join(tmpDir, f)).mtimeMs }))
      .sort((a, b) => b.mtime - a.mtime);
    if (!files.length) return null;
    return JSON.parse(fs.readFileSync(path.join(tmpDir, files[0].name), 'utf8')).intent_class || null;
  } catch { return null; }
}

function isStage0ViaTmpFiles() {
  try {
    const files = fs.readdirSync(os.tmpdir());
    return files.some(f => f.startsWith('stage0-intent-class-') || f.startsWith('stage0-runtime-assertions-'));
  } catch { return false; }
}

