// ── Audit 4: Tool Call Audit ───────────────────────────────────────────────────

function auditToolCalls(msg, hayLow, hayOrig, warnings, blocks) {
  if (!msg || msg.length < 50) return;

  const scripts = [
    { name: 'persist-verdict.py',   step: 'Step 9',   regex: /python(?:\.exe)?\s+[^\n]{0,200}persist-verdict\.py/i },
    { name: 'persist-knowledge.py', step: 'Step 9.5', regex: /python(?:\.exe)?\s+[^\n]{0,200}persist-knowledge\.py/i },
    { name: 'verify-persistence.py',step: 'Step 9.6', regex: /python(?:\.exe)?\s+[^\n]{0,200}verify-persistence\.py/i },
  ];
  const missingScripts = scripts.filter(s => !s.regex.test(hayOrig));
  const hasBrainAudit  = hayLow.includes('brain information flow audit') || hayLow.includes('## brain information flow');
  const hasVerdictMark = /##\s*verdict:\s*(mountain|provisional_mountain|side_hustle|insufficient_signal|kill)/i.test(hayOrig);
  const hasKBFired     = hayLow.includes('knowledge fired during this analysis') || hayLow.includes('## knowledge fired');

  if (!/(?:interpret.*topic|branches?\s*detect|echo.*interpret|which.*branch)/i.test(hayOrig))
    warnings.push('⚠ STAGE0 SOFT: No topic disambiguation evidence. Consider Step 2.5 echo.');

  const isKill = /VERDICT:\s*KILL/i.test(hayOrig);
  const usesMM03 = /MM-03|revenue.{0,30}floor|triangulat.{0,20}auto.?kill/i.test(hayOrig);
  if (isKill && usesMM03 && !/triangulated_range|burn_math|financial.triangulator.*return/i.test(hayOrig)
      && !/MM-03.*(?:INCONCLUSIVE|skipped|did not run)/i.test(hayOrig))
    warnings.push('⚠ STAGE0 SOFT: KILL via MM-03 without financial-triangulator data. Use INCONCLUSIVE or cite other grounds.');

  const failures = [];
  if (missingScripts.length) failures.push(`Missing scripts: ${missingScripts.map(s => `${s.name} (${s.step})`).join(', ')}`);
  if (!hasBrainAudit)  failures.push('Missing ## Brain Information Flow Audit section');
  if (!hasVerdictMark) failures.push('Missing deterministic VERDICT marker');
  if (!hasKBFired)     failures.push('Missing ## Knowledge fired during this analysis section');

  if (failures.length) {
    blocks.push([
      'STAGE0 TOOL CALL AUDIT — BLOCKED',
      failures.map((f, i) => `  ${i+1}. ${f}`).join('\n'),
      'Regenerate with all 6 required elements (scripts + sections + verdict marker).',
    ].join('\n'));
  }
}

// ── Audit 5: Content Extraction (warn-only) ────────────────────────────────────

function auditContentExtraction(msg, user, hayLow, warnings) {
  if (!msg || msg.length < 200) return;
  const urls = (user || '').match(/https?:\/\/[^\s)>"'\]]+/gi) || [];
  if (!urls.length) return;

  const hasEvidence = [/yt-dlp/i,/tikwm/i,/dump-json/i,/write-info-json/i,/flat-playlist/i,
    /comment.*list.*api/i,/ai-multimodal/i,/deep.comment.miner/i,/transcript/i,/audio.transcrib/i,
    /whisper/i,/\.json\s*endpoint/i].some(r => r.test(hayLow));
  if (hasEvidence) return;

  const platUrls = urls.filter(u => /tiktok\.com|youtube\.com|youtu\.be|reddit\.com|instagram\.com/i.test(u));
  warnings.push(`⚠ CONTENT EXTRACTION (${urls.length} URL(s), ${platUrls.length} platform): no extraction tool evidence. Use yt-dlp/tikwm/ai-multimodal per Step 2.7.`);
}

// ── Audit 6: Claim Verification (warn-only) ────────────────────────────────────

function auditClaimVerification(msg, user, hayLow, warnings) {
  if (!msg || msg.length < 200) return;
  const urls = (user || '').match(/https?:\/\/[^\s)>"'\]]+/gi) || [];
  if (!urls.length) return;

  const w = [];
  const hasClaimSet = hayLow.includes('claim_set') || hayLow.includes('claim set') || hayLow.includes('claim expansion');
  if (!hasClaimSet) w.push(`${urls.length} URL(s) provided but no CLAIM_SET section — Step 2.8 may be skipped`);

  if (/revenue|income|\$\d|earnings|profit/i.test(msg)
      && !/triangulat|3\+?\s*(?:independent|source)|cross.?verif/i.test(hayLow)
      && hasClaimSet)
    w.push('Revenue/income refs without triangulation evidence — P0 claims need 3+ source types');

  if (w.length) warnings.push(`⚠ CLAIM VERIFICATION:\n${w.map((x,i)=>`  ${i+1}. ${x}`).join('\n')}`);
}

// ── Audit 7: Wave 2 Enforcement ────────────────────────────────────────────────

function auditWave2(payload, msg, blocks) {
  try {
    let enforceMode = 'enforce';
    try {
      const cfg = JSON.parse(fs.readFileSync(path.join(process.cwd(), '.claude', '.ck.json'), 'utf8'));
      enforceMode = cfg?.stage0?.wave2Enforcement || 'enforce';
    } catch {}
    if (enforceMode === 'off') return;

    const tmpDir = os.tmpdir();
    const wave1 = fs.readdirSync(tmpDir)
      .filter(f => f.startsWith('stage0-wave1-receipt-') && f.endsWith('.json'))
      .map(f => ({ name: f, mtime: fs.statSync(path.join(tmpDir, f)).mtimeMs }))
      .sort((a, b) => b.mtime - a.mtime);
    if (!wave1.length) return;

    const caseId = wave1[0].name.replace('stage0-wave1-receipt-', '').replace('.json', '');
    if (fs.existsSync(path.join(tmpDir, `stage0-wave2-receipt-${caseId}.json`))) return;

    const text = msg || getLastAssistantText(payload);
    if (!looksLikeVerdict(text)) return;

    const EXEMPT = new Set(['EXPLORATION_ONGOING','INSUFFICIENT_SIGNAL','KILL','HARD_KILL']);
    const vm = text.match(/VERDICT[:\s*]+([A-Z_]+)/);
    if (vm && EXEMPT.has(vm[1].trim())) return;

    const BLOCKING_INTENTS = new Set(['operator_layer','power_law_hunt','grey_zone_adjacent']);
    let intentClass = null;
    try {
      const p = path.join(tmpDir, `stage0-intent-class-${caseId}.json`);
      if (fs.existsSync(p)) intentClass = JSON.parse(fs.readFileSync(p, 'utf8')).intent_class || null;
    } catch {}

    if (intentClass && BLOCKING_INTENTS.has(intentClass)) {
      blocks.push(`[stage0-wave2-enforcement] HARD BLOCK: Wave 2 MANDATORY for ${intentClass}. Case ${caseId}. Spawn: deep-comment-miner, ground-truth-fetcher, full-coverage-ingest, financial-triangulator, persona-insider-loader, hypothesis-generator.`);
      return;
    }

    const cm = text.match(/\*?\*?[Cc]onfidence[:\s*]+([0-9.]+)/);
    const conf = cm ? parseFloat(cm[1]) : 1.0;
    if (!isNaN(conf) && conf < 0.8) {
      const m = `[stage0-wave2-enforcement] BLOCK: Case ${caseId} | Conf ${conf} < 0.8 | Verdict ${vm?.[1]||'?'} | Intent ${intentClass||'?'}. Run Wave 2 (≥4 agents) OR downgrade to EXPLORATION_ONGOING.`;
      if (enforceMode === 'warn') process.stderr.write(m + '\n');
      else blocks.push(m);
    }
  } catch (e) {
    process.stderr.write(`[stage0-wave2-enforcement] error (fail-open): ${e.message}\n`);
  }
}

