// ══════════════════════════════════════════════════════════════════════════════

function runCashflowAudit(payload) {
  if (payload.tool_name !== 'Write') { console.log(JSON.stringify({ decision: 'approve' })); return; }

  const filePath = (payload.tool_input || payload.input || {}).file_path || '';
  const content  = (payload.tool_input || payload.input || {}).content  || '';

  const AUDIT_PATHS = [/verdict.*\.md$/i,/verdicts\/.*\.md$/i,/startup.*output/i,/analysis.*\.md$/i,
    /circuit.*\.md$/i,/position.*\.md$/i,/stage0.*synthesis/i,/stage0-.*\.json$/i];
  const SKIP_PATHS  = [/node_modules/,/\.git/,/test/i,/spec/i,/plan\.md$/i,/phase-\d+/i];

  if (!filePath || SKIP_PATHS.some(p => p.test(filePath)) || !AUDIT_PATHS.some(p => p.test(filePath))) {
    console.log(JSON.stringify({ decision: 'approve' })); return;
  }

  const PATTERNS = [
    { pattern: /\$[\d,]+\s*(\/mo|MRR|ARR|month|monthly|revenue|income)/gi, engine: 'simulate' },
    { pattern: /\$[\d,]+k?\s*(per\s*month|a\s*month)/gi, engine: 'simulate' },
    { pattern: /(\d+)\s*(months?|weeks?|days?)\s*(runway|survive|last|left)/gi, engine: 'runway' },
    { pattern: /death\s*date|run\s*out\s*of\s*(cash|money)/gi, engine: 'runway' },
    { pattern: /survival\s*probability/gi, engine: 'runway' },
    { pattern: /(passive|leveraged|scalable|compound)\s*(income|revenue|business)/gi, engine: 'leverage' },
    { pattern: /leverage\s*score/gi, engine: 'leverage' },
    { pattern: /(price|charge|cost)\s*(at|of)?\s*\$[\d,]+/gi, engine: 'hormozi' },
    { pattern: /value\s*(equation|score)/gi, engine: 'hormozi' },
    { pattern: /(CCC|cash\s*conversion|payment\s*cycle)/gi, engine: 'velocity' },
    { pattern: /(DSO|DIO|DPO|days\s*receivable|days\s*payable)/gi, engine: 'velocity' },
    { pattern: /(nash\s*equilibrium|BATNA|power\s*balance)/gi, engine: 'game' },
    { pattern: /(walk[\s-]?away|negotiation\s*strategy)/gi, engine: 'game' },
    { pattern: /failure\s*mode|vulnerability|inversion/gi, engine: 'munger' },
    { pattern: /barbell\s*(allocation|strategy)/gi, engine: 'taleb' },
    { pattern: /breakeven\s*(in|by|month)\s*\d+/gi, engine: 'simulate' },
    { pattern: /monte\s*carlo/gi, engine: 'simulate' },
  ];

  const violations = []; const seen = new Set();
  for (const { pattern, engine } of PATTERNS) {
    pattern.lastIndex = 0; let m;
    while ((m = pattern.exec(content)) !== null) {
      const lineNum = content.substring(0, m.index).split('\n').length;
      const key = `${lineNum}-${engine}`;
      if (seen.has(key)) continue; seen.add(key);
      const ctx = content.substring(Math.max(0, m.index - 250), Math.min(content.length, m.index + m[0].length + 100));
      if (!/\[COMPUTED:(\w+)\]/i.test(ctx) && !/\[UNCOMPUTED:(\w+)\|/i.test(ctx))
        violations.push({ claim: m[0].substring(0, 60) + (m[0].length > 60 ? '...' : ''), line: lineNum, engine });
    }
  }

  if (!violations.length) { console.log(JSON.stringify({ decision: 'approve' })); return; }

  const isDegraded = content.includes('MONEY_INTELLIGENCE_DEGRADED') || content.includes('[DEGRADED_NO_COMPUTATION]');
  if (isDegraded) {
    console.log(JSON.stringify({ decision: 'allow', additionalContext: `[stage0-cashflow-audit] DEGRADED: ${violations.length} uncomputed claims allowed` }));
    return;
  }

  const list = violations.slice(0, 8).map(v => `  Line ${v.line}: "${v.claim}" → [COMPUTED:${v.engine}]`).join('\n')
    + (violations.length > 8 ? `\n  ... and ${violations.length - 8} more` : '');
  console.log(JSON.stringify({
    decision: 'block',
    reason: `CASHFLOW AUDIT FAILED: ${violations.length} uncomputed claim(s) in ${filePath}\n${list}\nRun money-calc-router.py and add [COMPUTED:engine] or [UNCOMPUTED:engine|reason:...] tags.`,
  }));
}

